const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point(-70.647985, -34.752733);
    const basins = ee.FeatureCollection('WWF/HydroSHEDS/v1/Basins/hybas_7');
    const basin = basins.filterBounds(point).first();
    const geometry = basin.geometry();

    const date1 = '2021-12-18';
    const date2 = '2023-12-18';
    const dateRangeDays = 5; // Use a +/- 5 day window to find a clear image

    // 2. Data Acquisition & Processing Function
    const getSnowCover = function(dateStr, geom) {
        const centerDate = ee.Date(dateStr);
        const startDate = centerDate.advance(-dateRangeDays, 'day');
        const endDate = centerDate.advance(dateRangeDays, 'day');

        let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
            .filterBounds(geom)
            .filterDate(startDate, endDate)
            .sort('CLOUDY_PIXEL_PERCENTAGE');

        if (collection.size().getInfo() === 0) {
            return null; // No images found in the primary collection
        }

        const image = ee.Image(collection.first());

        // Cloud masking using the Scene Classification Layer (SCL)
        // Classes 4(veg), 5(bare), 6(water), 7(unclassified), 11(snow/ice) are good
        const scl = image.select('SCL');
        const mask = scl.eq(4).or(scl.eq(5)).or(scl.eq(6)).or(scl.eq(7)).or(scl.eq(11));

        // Calculate NDSI: (Green - SWIR1) / (Green + SWIR1) -> (B3 - B11) / (B3 + B11)
        const ndsi = image.normalizedDifference(['B3', 'B11']).rename('NDSI');

        // Threshold NDSI to identify snow (a common threshold is 0.4)
        const snow = ndsi.gt(0.4).updateMask(mask).rename('snow');

        const stats = snow.reduceRegion({
            reducer: ee.Reducer.sum().combine({
                reducer2: ee.Reducer.count(),
                sharedInputs: true
            }),
            geometry: geom,
            scale: 1000,
            maxPixels: 1e9
        });
        return ee.Dictionary(stats).combine({
            'cloud_percent': image.get('CLOUDY_PIXEL_PERCENTAGE')
        });
    };

    // 3. Calculation for both dates
    const stats2021 = getSnowCover(date1, geometry);
    const stats2023 = getSnowCover(date2, geometry);

    if (!stats2021 || !stats2023) {
        console.log("Evidence: No Sentinel-2 images found for one or both date ranges.");
        console.log("C1");
        return;
    }

    const result2021 = stats2021.getInfo();
    const result2023 = stats2023.getInfo();

    // 4. Validation & Final Answer
    if (result2021 === null || result2023 === null || result2021.snow === null || result2023.snow === null) {
        console.log("Evidence: Calculation failed, a result was null.");
        console.log("C3");
        return;
    }

    if (result2021.snow_count === 0 || result2023.snow_count === 0) {
        console.log("Evidence: No valid (non-cloud) pixels found in the basin for analysis.");
        console.log(`2021 Valid Pixels: ${result2021.snow_count}`);
        console.log(`2023 Valid Pixels: ${result2023.snow_count}`);
        console.log("C2");
        return;
    }

    const snowPixels2021 = result2021.snow;
    const snowPixels2023 = result2023.snow;
    const cloudPercent2021 = result2021.cloud_percent;
    const cloudPercent2023 = result2023.cloud_percent;

    console.log(`2021 Snow Pixels (NDSI > 0.4): ${snowPixels2021.toFixed(0)}`);
    console.log(`2021 Image Cloud Cover: ${cloudPercent2021.toFixed(2)}%`);
    console.log(`2023 Snow Pixels (NDSI > 0.4): ${snowPixels2023.toFixed(0)}`);
    console.log(`2023 Image Cloud Cover: ${cloudPercent2023.toFixed(2)}%`);

    if (snowPixels2023 > snowPixels2021) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error("Authentication or Initialization error:", e);
        console.log("D");
    }
}

initEE().catch(e => {
    console.error(e);
    console.log("D");
});
